const express = require('express');
const session = require('express-session');
const { scrypt, randomBytes, timingSafeEqual } = require('node:crypto');
const { promisify } = require('node:util');

const scryptAsync = promisify(scrypt);

// --- password hashing (stdlib scrypt, per-user random salt) ---

async function hashPassword(password) {
  const salt = randomBytes(16);
  const key = await scryptAsync(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return timingSafeEqual(key, await scryptAsync(password, salt, 64));
}

// Verified against when the username is unknown, so response time doesn't reveal which usernames exist.
const dummyHash = hashPassword(randomBytes(16).toString('hex'));

// chisle: in-memory user store; swap for a DB lookup returning { id, passwordHash }
const users = new Map();

// --- rate limiting of failed attempts ---

const WINDOW_MS = 15 * 60 * 1000;
const MAX_PER_IP_USER = 5; // guessing one account
const MAX_PER_IP = 20; // spraying many accounts
// chisle: in-memory, single process; move to Redis when running more than one instance
const attempts = new Map(); // key -> { count, resetAt }

function retryAfterMs(key, max) {
  const a = attempts.get(key);
  return a && a.resetAt > Date.now() && a.count >= max ? a.resetAt - Date.now() : 0;
}

function recordAttempt(key) {
  const now = Date.now();
  const a = attempts.get(key);
  if (a && a.resetAt > now) a.count++;
  else attempts.set(key, { count: 1, resetAt: now + WINDOW_MS });
}

setInterval(() => {
  const now = Date.now();
  for (const [key, a] of attempts) if (a.resetAt <= now) attempts.delete(key);
}, WINDOW_MS).unref();

// --- app ---

const app = express();
// Behind a reverse proxy, uncomment so req.ip is the client and not the proxy:
// app.set('trust proxy', 1);
app.use(express.json());
app.use(
  session({
    // chisle: default MemoryStore leaks and is per-process; use connect-redis or similar in production
    secret: process.env.SESSION_SECRET,
    name: 'sid',
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 24 * 60 * 60 * 1000,
    },
  })
);

app.post('/login', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (
    typeof username !== 'string' || typeof password !== 'string' ||
    !username || !password || username.length > 254 || password.length > 1024
  ) {
    return res.status(400).json({ error: 'Invalid request' });
  }

  const ipKey = `ip:${req.ip}`;
  const userKey = `user:${req.ip}:${username.toLowerCase()}`;
  const wait = Math.max(retryAfterMs(ipKey, MAX_PER_IP), retryAfterMs(userKey, MAX_PER_IP_USER));
  if (wait) {
    res.set('Retry-After', Math.ceil(wait / 1000));
    return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }

  // Count before the slow hash so a parallel burst can't slip past the limit; refunded on success.
  recordAttempt(ipKey);
  recordAttempt(userKey);

  const user = users.get(username.toLowerCase());
  const ok = await verifyPassword(password, user ? user.passwordHash : await dummyHash);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid username or password' });

  attempts.delete(userKey);
  const ip = attempts.get(ipKey);
  if (ip) ip.count--;

  // New session ID on login prevents session fixation.
  await new Promise((resolve, reject) => req.session.regenerate((err) => (err ? reject(err) : resolve())));
  req.session.userId = user.id;
  res.json({ ok: true });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.get('/me', requireAuth, (req, res) => res.json({ userId: req.session.userId }));

if (require.main === module) {
  if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');
  app.listen(process.env.PORT || 3000);
}

module.exports = { app, users, hashPassword };

process.env.SESSION_SECRET = 'test';
const test = require('node:test');
const assert = require('node:assert');
const { app, users, hashPassword } = require('./server');

test('login, session, lockout', async (t) => {
  users.set('alice', { id: 1, passwordHash: await hashPassword('correct horse') });
  const server = app.listen(0);
  t.after(() => server.close());
  const base = `http://localhost:${server.address().port}`;
  const login = (username, password) =>
    fetch(`${base}/login`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ username, password }),
    });

  assert.equal((await fetch(`${base}/me`)).status, 401);

  const good = await login('alice', 'correct horse');
  assert.equal(good.status, 200);
  const cookie = good.headers.get('set-cookie').split(';')[0];
  assert.equal((await fetch(`${base}/me`, { headers: { cookie } })).status, 200);

  await fetch(`${base}/logout`, { method: 'POST', headers: { cookie } });
  assert.equal((await fetch(`${base}/me`, { headers: { cookie } })).status, 401);

  assert.equal((await login('nobody', 'x')).status, 401);
  for (let i = 0; i < 5; i++) assert.equal((await login('alice', 'wrong')).status, 401);
  const locked = await login('alice', 'correct horse');
  assert.equal(locked.status, 429);
  assert.ok(locked.headers.get('retry-after'));
});

